    /**
     * Method to retrieve the Rate via an RatePrimaryKey.
     * @param 	id Long
     * @return 	Rate
     * @exception ProcessingException - Thrown if processing any related problems
     * @exception IllegalArgumentException 
     */
    @SuppressWarnings("unused")
    @QueryHandler
    public Rate handle( FindRateQuery query ) 
    throws ProcessingException, IllegalArgumentException {
    	return find( query.getFilter().getRateId() );
    }
    
    /**
     * Method to retrieve a collection of all Rates
     *
     * @param	query	FindAllRateQuery 
     * @return 	List<Rate> 
     * @exception ProcessingException Thrown if any problems
     */
    @SuppressWarnings("unused")
    @QueryHandler
    public List<Rate> handle( FindAllRateQuery query ) throws ProcessingException {
    	return findAll( query );
    }



/**
 * emit to subscription queries of type FindRate,
 * but only if the id matches
 *
 * @param		entity	Rate
 */
	protected void emitFindRate( Rate entity ) {
		LOGGER.info("handling emitFindRate" );
		
	    queryUpdateEmitter.emit(FindRateQuery.class,
	                            query -> query.getFilter().getRateId().equals(entity.getRateId()),
	                            entity);
	}
	
	/**
	 * unconditionally emit to subscription queries of type FindAllRate
	 * 
	 * @param		entity	Rate
	 */
	protected void emitFindAllRate( Rate entity ) {
		LOGGER.info("handling emitFindAllRate" );
		
	    queryUpdateEmitter.emit(FindAllRateQuery.class,
	                            query -> true,
	                            entity);
	}

